export function SafeArea({
  respectSafeArea = {{respectSafeArea}},
  device = "{{device}}",
  content = "{{content}}",
  accent = "{{accent}}",
}) {
  return (
    <div style={{ position: "relative", width: 160, height: 200, margin: "0 auto", background: "#241430", borderRadius: 24, padding: 10, boxSizing: "border-box", fontFamily: "system-ui, sans-serif", fontSize: 10, color: "#241430aa" }}>
      <div style={{ position: "absolute", top: 10, left: "50%", transform: "translateX(-50%)", background: "#000", zIndex: 2, width: device === "notch" ? 60 : 40, height: device === "notch" ? 16 : 10, borderRadius: device === "notch" ? "0 0 10px 10px" : 999 }} />
      <div style={{ marginTop: respectSafeArea ? 34 : 10, padding: 10, borderRadius: 8, color: "#241430", fontWeight: 600, textAlign: "center", background: accent }}>{content}</div>
      <p style={{ position: "absolute", bottom: -30, left: 0, right: 0, textAlign: "center" }}>
        {respectSafeArea ? `Padded clear of the ${device}` : `Ignoring the safe area \u2014 text sits under the ${device}`}
      </p>
    </div>
  );
}
